import{_ as t,o,c as a,ah as n}from"./chunks/framework.ChH6X6u6.js";const u=JSON.parse('{"title":"Internal edPage panel","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"en/admission/staff-edpage/index.md","filePath":"src/en/admission/staff-edpage/index.md"}'),i={name:"en/admission/staff-edpage/index.md"};function s(l,e,r,d,h,c){return o(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="internal-edpage-panel" tabindex="-1">Internal edPage panel <a class="header-anchor" href="#internal-edpage-panel" aria-label="Permalink to &quot;Internal edPage panel&quot;">​</a></h1><p>The internal Era Admission panel is the tool reserved for the edPage team to manage the lifecycle of schools signed up online: granting a license, ending a demo early, or purging an expired school. It has nothing to do with a client school&#39;s own user account — it&#39;s an entirely separate access.</p><h2 id="logging-into-the-panel" tabindex="-1">Logging into the panel <a class="header-anchor" href="#logging-into-the-panel" aria-label="Permalink to &quot;Logging into the panel&quot;">​</a></h2><ol><li>Go to the staff login page, reachable on ERA&#39;s central domain (the one hosting the signup site, not a school&#39;s subdomain).</li><li>Enter your <strong>staff account</strong> email address and password — this account is independent of any school account, it only exists for the edPage team.</li><li>Submit. You land on the schools list.</li></ol><p>The staff login form is deliberately minimal (no public signup, no two-factor authentication, no self-service password reset): staff accounts are created by hand, not through a public flow.</p><h2 id="viewing-the-schools-list" tabindex="-1">Viewing the schools list <a class="header-anchor" href="#viewing-the-schools-list" aria-label="Permalink to &quot;Viewing the schools list&quot;">​</a></h2><p>Once logged in, the &quot;Schools&quot; page lists every school that has signed up, with for each one:</p><ul><li>its name and subdomain;</li><li>its <strong>status</strong>: free, demo, licensed, or expired;</li><li>its active <strong>modules</strong> (none on free; all on demo; whichever are actually licensed on licensed; none on expired);</li><li>its <strong>hosting formula</strong> (self-hosted or managed);</li><li>the demo end date, the date maintenance is paid through, and how long the school has been expired, whichever applies.</li></ul><p>Each row then offers the actions available for that school, described below — some only appear for certain statuses.</p><h2 id="granting-a-license" tabindex="-1">Granting a license <a class="header-anchor" href="#granting-a-license" aria-label="Permalink to &quot;Granting a license&quot;">​</a></h2><p>Available for any school, regardless of its current status.</p><ol><li>On the row for the school in question, click <strong>License</strong>.</li><li>In the dialog, check the modules to grant (or the &quot;Full offer&quot; option for every module at once). Each module&#39;s price is shown next to its name.</li><li>Fill in, if needed, the date maintenance is paid through. Left blank, it defaults to one year from today.</li><li>Confirm with <strong>Grant license</strong>.</li></ol><p>The school immediately moves to &quot;Licensed&quot; status, with the checked modules active, while staying hosted on edPage&#39;s infrastructure (the &quot;Managed&quot; formula). If the school ultimately needs to host its own installation instead (the &quot;Self-hosted&quot; formula), that switch is done through a dedicated command-line tool, outside this panel — don&#39;t use this action for that case.</p><p>This action can also be used to <strong>modify</strong> the license of an already licensed school (adding a module, extending maintenance): simply apply it again with the new values.</p><h2 id="ending-a-demo-manually" tabindex="-1">Ending a demo manually <a class="header-anchor" href="#ending-a-demo-manually" aria-label="Permalink to &quot;Ending a demo manually&quot;">​</a></h2><p>Available only for a school with &quot;Demo&quot; status. The action doesn&#39;t appear on other statuses.</p><ol><li>On the school&#39;s row, click <strong>End demo</strong>.</li><li>Confirm in the dialog — the action is immediate.</li></ol><p>The school moves to &quot;Expired&quot; status and switches to read-only, exactly as if its demo had ended naturally at its scheduled deadline. Use this action to end a demo before its normal term (for example at the school&#39;s request, or in case of misuse) — it isn&#39;t needed in the ordinary course of things, since the demo ends on its own.</p><h2 id="purging-an-expired-school" tabindex="-1">Purging an expired school <a class="header-anchor" href="#purging-an-expired-school" aria-label="Permalink to &quot;Purging an expired school&quot;">​</a></h2><p>Available only for a school with &quot;Expired&quot; status. This action is <strong>final and irreversible</strong>.</p><ol><li>On the school&#39;s row, click <strong>Purge</strong>.</li><li>Read the warning message in the dialog carefully: it states that the school, its database, and its storage will be deleted immediately, with no grace period and no way to undo it.</li><li>Confirm with <strong>Delete permanently</strong>.</li></ol><p>In the ordinary course of things, a school expired for too long is purged automatically once its grace period elapses. Use this manual action only to purge a school ahead of that automatic deadline — for example at the school&#39;s explicit request to delete its data without waiting.</p>',22)])])}const p=t(i,[["render",s]]);export{u as __pageData,p as default};
